use super::*;
#[test]
fn original_source_parent_closes_lending_before_child_then_separate_terminal_header(){
 let row:serde_json::Value=serde_json::from_str(include_str!("../📐️.json")).unwrap();let s=&row["stock"];let mut bank=RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize};
 let(mut authority,p)=JobPayloadAuthority::admit(OperationId(row["operation"].as_u64().unwrap()),Generation(row["generation"].as_u64().unwrap()),RetainedCloneGrant{maximum_items:1,..bank}).result.unwrap().unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;
 let(token,p)=CancelToken::admit_root(RetainedCloneGrant{maximum_items:1,..bank}).result.unwrap().unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;
 let(mut parent,p)=OriginalCallerSourceParent::admit(authority,token,RetainedCloneGrant{maximum_items:1,..bank}).result.map_err(|(error,..)|error).unwrap();bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;let identity=parent.source_identity().unwrap();let source=parent.payload_authority_identity().unwrap();let demand=parent.retirement_demands().unwrap();assert_eq!(demand,RetirementDemand{depth:1,..Default::default()});
 let denied=parent.close_step(Default::default());assert_eq!(denied.work,row["deniedWork"].as_u64().unwrap());assert_eq!(denied.result.unwrap().progress(),RetainedCloneProgress::default());assert!(parent.lending_is_open());assert_eq!(parent.source_identity().unwrap(),identity);assert_eq!(parent.payload_authority_identity().unwrap(),source);
 let mut work=Vec::new();for turn in 0..s["maximumTurns"].as_u64().unwrap(){if parent.terminal_is_empty(){break;}let next=parent.close_step(RetainedCloneGrant{maximum_items:1,..bank});work.push(next.work);let p=next.result.unwrap().progress();assert!(p.fits(bank));assert_eq!(p.copied_bytes,row["copyBytes"].as_u64().unwrap()as usize);bank.maximum_items-=p.copied_items;bank.maximum_copy_bytes-=p.copied_bytes;bank.maximum_capacity_bytes-=p.retained_capacity_bytes;bank.maximum_release_bytes-=p.released_bytes;if turn==0{assert!(!parent.lending_is_open());assert_eq!(parent.source_identity().unwrap(),identity);assert_eq!(parent.payload_authority_identity().unwrap(),source);}}
 assert!(parent.terminal_is_empty());assert_eq!(serde_json::to_value(work).unwrap(),row["actualWork"]);let cached=parent.close_step(Default::default());assert_eq!(cached.work,row["cachedWork"].as_u64().unwrap());assert_eq!(cached.result.unwrap().progress(),RetainedCloneProgress::default());drop(parent);
}
